async function addExpense(){try{await api('/api/admin/finance/expenses',{method:'POST',body:JSON.stringify({name:$('#expName').value,category:$('#expCategory').value,amount:Number($('#expAmount').value),date:$('#expDate').value,account:$('#expAccount').value,note:$('#expNote').value})});await loadFinance()}catch(e){alert(e.message)}}
