function downloadReconciliation(){const companyId=$('#reconCompany')?.value;if(!companyId){alert('Firma tanlang');return}window.location=`/api/admin/finance/reconciliation.xls?companyId=${encodeURIComponent(companyId)}&from=${encodeURIComponent($('#reconFrom')?.value||'')}&to=${encodeURIComponent($('#reconTo')?.value||'')}`}

function promosPane(){return `<div class="panel"><div class="toolbar"><button class="btn primary sm" onclick="addPromo()">+ Promo kod</button><button class="btn ghost sm" onclick="savePromos()">Saqlash</button></div><div id="promoList">${D.promos.map((p,i)=>promoRow(p,i)).join('')}</div></div>`}
function promoRow(p,i){return `<div class="promo-row" data-i="${i}"><input class="code" value="${esc(p.code)}" placeholder="KOD"><select class="type"><option value="percent" ${p.type==='percent'?'selected':''}>%</option><option value="fixed" ${p.type==='fixed'?'selected':''}>So‘m</option></select><input class="value" type="number" value="${p.value}" placeholder="Qiymat"><input class="min" type="number" value="${p.minTotal||0}" placeholder="Min summa"><input class="limit" type="number" value="${p.usageLimit||0}" placeholder="Limit"><input class="expires" type="date" value="${esc(p.expires||'')}"><select class="active"><option value="1" ${p.active?'selected':''}>Faol</option><option value="0" ${!p.active?'selected':''}>O‘chiq</option></select><button class="btn danger sm" onclick="removePromo(${i})">×</button></div>`}
function addPromo(){D.promos.push({code:'YANGI10',type:'percent',value:10,minTotal:0,active:true,usageLimit:100,used:0,expires:''});renderPane()}
function removePromo(i){D.promos.splice(i,1);renderPane()}
async function savePromos(){document.querySelectorAll('.promo-row').forEach(r=>{const p=D.promos[Number(r.dataset.i)];p.code=r.querySelector('.code').value.toUpperCase();p.type=r.querySelector('.type').value;p.value=Number(r.querySelector('.value').value);p.minTotal=Number(r.querySelector('.min').value);p.usageLimit=Number(r.querySelector('.limit').value);p.expires=r.querySelector('.expires').value;p.active=r.querySelector('.active').value==='1'});try{await api('/api/admin/promos',{method:'PUT',body:JSON.stringify({promos:D.promos})});alert('Promo kodlar saqlandi');await refresh()}catch(e){alert(e.message)}}
function areasPane(){return `<div class="panel area-editor"><h3>Parkent tumani yetkazib berish hududlari</h3><p class="muted">Har bir hududni alohida qatorda yozing. Mijoz checkoutda shu ro‘yxatdan majburiy tanlaydi. Yetkazib berish bepul.</p><textarea id="areasText">${esc((D.settings.delivery?.areas||[]).join('\n'))}</textarea><h3>Yetkazish vaqt oralig‘i</h3><textarea id="slotsText" style="min-height:120px">${esc((D.settings.delivery?.slots||[]).join('\n'))}</textarea><button class="btn primary" onclick="saveAreas()">Hududlarni saqlash</button></div>`}
async function saveAreas(){D.settings.delivery=D.settings.delivery||{};D.settings.delivery.free=true;D.settings.delivery.district='Parkent tumani';D.settings.delivery.areas=$('#areasText').value.split('\n').map(x=>x.trim()).filter(Boolean);D.settings.delivery.slots=$('#slotsText').value.split('\n').map(x=>x.trim()).filter(Boolean);await saveSettings('Hududlar saqlandi')}

function slidesPane(){const slides=Array.isArray(D.settings.heroSlides)?D.settings.heroSlides:[];return `<div class="panel"><div class="slider-admin-head"><div><h2 style="margin:0">Bosh sahifa slayderi</h2><p class="muted">Parkent tabiatini ko‘rsatish uchun maksimum 5 ta rasm. Rasmlar saytning yuqori qismida avtomatik almashib turadi.</p></div>${slides.length<5?`<label class="btn primary slider-upload-btn">+ Yangi rasm qo‘shish<input type="file" accept="image/jpeg,image/png,image/webp" onchange="addHeroSlide(event)"></label>`:''}</div><div class="slider-admin-grid">${slides.length?slides.map((x,i)=>`<div class="slider-admin-row"><div class="slide-order">${i+1}</div><img class="slider-admin-preview" src="${esc(x.image)}" alt="Slayd ${i+1}"><div class="slider-admin-info"><b>Slayd ${i+1}</b><span class="muted">${x.active===false?'O‘chirilgan':'Faol'}</span><div class="slider-admin-actions"><label class="btn ghost sm slider-upload-btn">Rasmni almashtirish<input type="file" accept="image/jpeg,image/png,image/webp" onchange="replaceHeroSlide(event,${i})"></label><button class="btn ghost sm" type="button" onclick="moveHeroSlide(${i},-1)" ${i===0?'disabled':''}>↑</button><button class="btn ghost sm" type="button" onclick="moveHeroSlide(${i},1)" ${i===slides.length-1?'disabled':''}>↓</button><button class="btn ghost sm" type="button" onclick="toggleHeroSlide(${i})">${x.active===false?'Faollashtirish':'O‘chirish'}</button></div></div><button class="btn danger sm" type="button" onclick="removeHeroSlide(${i})">Olib tashlash</button></div>`).join(''):`<div class="slide-empty"><b>Hozircha slayd yo‘q.</b><br>Yuqoridagi “Yangi rasm qo‘shish” orqali rasm yuklang.</div>`}</div><div class="notice slider-tip"><b>Tavsiya:</b> gorizontal rasm ishlating (taxminan 1920×600 yoki 1600×500). JPG, PNG, WEBP. Maksimum 5 ta. Saytda har 5 soniyada navbat bilan almashadi.</div><div class="pages-savebar"><button class="btn primary" onclick="saveHeroSlides()">Slayderni saqlash</button></div></div>`}
function optimizeSlideFile(file,cb){if(!file)return;if(!/^image\/(jpeg|png|webp)$/.test(file.type)){alert('Faqat JPG, PNG yoki WEBP rasm tanlang.');return}if(file.size>12*1024*1024){alert('Rasm 12 MB dan katta bo‘lmasin.');return}const img=new Image(),reader=new FileReader();reader.onload=()=>{img.onload=()=>{const maxW=1920,maxH=900,scale=Math.min(1,maxW/img.width,maxH/img.height),w=Math.max(1,Math.round(img.width*scale)),h=Math.max(1,Math.round(img.height*scale)),c=document.createElement('canvas');c.width=w;c.height=h;c.getContext('2d').drawImage(img,0,0,w,h);let data;try{data=c.toDataURL('image/webp',.86)}catch{data=c.toDataURL('image/jpeg',.88)};cb(data)};img.src=reader.result};reader.readAsDataURL(file)}
function addHeroSlide(e){const f=e.target.files?.[0];if(!f)return;D.settings.heroSlides=Array.isArray(D.settings.heroSlides)?D.settings.heroSlides:[];if(D.settings.heroSlides.length>=5){alert('Maksimum 5 ta rasm mumkin.');return}optimizeSlideFile(f,data=>{D.settings.heroSlides.push({id:'slide-'+Date.now(),image:data,active:true});renderPane()})}
function replaceHeroSlide(e,i){const f=e.target.files?.[0];if(!f)return;optimizeSlideFile(f,data=>{D.settings.heroSlides[i].image=data;renderPane()})}
function removeHeroSlide(i){D.settings.heroSlides.splice(i,1);renderPane()}
function moveHeroSlide(i,d){const a=D.settings.heroSlides,j=i+d;if(j<0||j>=a.length)return;[a[i],a[j]]=[a[j],a[i]];renderPane()}
function toggleHeroSlide(i){D.settings.heroSlides[i].active=D.settings.heroSlides[i].active===false?true:false;renderPane()}
async function saveHeroSlides(){await saveSettings('Bosh sahifa slayderi saqlandi')}

function pagesPane(){const s=D.settings,co=s.company||{},mp=s.map||{},ft=s.footer||{},cu=s.catalogUi||{},ui=s.ui||{},tm=s.testMode||{},hp=s.homePromos||{},pl=hp.left||{},pc=hp.center||{},pr=hp.right||{},bn=Array.isArray(s.benefits)?s.benefits:[];const ce=typeof cu.eyebrow==='object'?cu.eyebrow:{uz:cu.eyebrow||'MAHSULOTLAR KATALOGI',ru:'КАТАЛОГ ТОВАРОВ'};return `<div class="panel"><div class="full-editor-note"><b>To‘liq sahifa muharriri.</b> Saytdagi asosiy matnlar, UZ/RU yozuvlar, promo bannerlar, logotip, aloqa, rekvizitlar va SEO shu yerdan boshqariladi.</div><div class="form-grid">
<h3 class="wide">Logotip va brend</h3><div class="wide logo-editor"><div>${D.logo?`<img src="${D.logo}" alt="Logo">`:`<img src="logo.png" alt="Logo">`}</div><div><h3>Sayt logotipi</h3><p class="muted">JPG, PNG yoki WEBP. Rasm avtomatik optimallashtiriladi.</p><div class="logo-actions"><label class="btn primary sm">Logotip tanlash<input type="file" accept="image/jpeg,image/png,image/webp" hidden onchange="setSiteLogo(event)"></label>${D.logo?`<button class="btn danger sm" type="button" onclick="removeSiteLogo()">Yuklangan logoni olib tashlash</button>`:''}</div></div></div>
<label>Sayt nomi<input id="siteName" value="${esc(s.siteName||'')}"></label><label>Domen<input id="siteDomain" value="${esc(s.siteDomain||'')}"></label><label>Dizayn<select id="theme"><option value="original" ${s.theme==='original'?'selected':''}>Original</option><option value="modern" ${s.theme==='modern'?'selected':''}>Modern</option><option value="classic" ${s.theme==='classic'?'selected':''}>Classic</option></select></label><label>Logotip o‘lchami (48–100 px)<input id="logoSize" type="number" min="48" max="100" value="${Number(ui.logoSize||68)}"></label><div class="wide contact-settings-card"><div><b>📞 Sayt tepasidagi aloqa ma’lumotlari</b><small>Saqlanganda yuqori panel, Aloqa bo‘limi va footer real vaqtda yangilanadi.</small></div></div><label>Telefon raqami<input id="phone" value="${esc(s.phone||'')}" placeholder="+998 90 123 45 67"></label><label>Telegram havola<input id="telegram" value="${esc(s.telegram||'')}" placeholder="https://t.me/..."></label><label>Email<input id="email" value="${esc(s.email||'')}"></label>
<h3 class="wide section-card">Test rejimi</h3><div class="wide test-toggle-box"><input id="testModeActive" type="checkbox" ${tm.active===false?'':'checked'}><label for="testModeActive"><b>Sayt tepasida test rejimi yozuvini ko‘rsatish</b></label></div><label class="wide">Test rejimi matni<input id="testModeText" value="${esc(tm.text||'Saytimiz hozirda test rejimida ishlamoqda')}"></label>
<h3 class="wide section-card">Yuqori yozuv</h3><label>Teglayn UZ<input id="tagUz" value="${esc(s.tagline?.uz||'')}"></label><label>Teglayn RU<input id="tagRu" value="${esc(s.tagline?.ru||'')}"></label>
<h3 class="wide section-card">Bosh sahifa — markaziy slayder yozuvi</h3><label>Markaz sarlavha UZ<input id="centerTitleUz" value="${esc(pc.title?.uz||'')}"></label><label>Markaz sarlavha RU<input id="centerTitleRu" value="${esc(pc.title?.ru||'')}"></label><label>Markaz matn UZ<input id="centerTextUz" value="${esc(pc.text?.uz||'')}"></label><label>Markaz matn RU<input id="centerTextRu" value="${esc(pc.text?.ru||'')}"></label>
<h3 class="wide section-card">Bosh sahifa — chap promo banner</h3><div class="wide promo-image-editor">${pl.image?`<img src="${pl.image}" alt="Chap promo">`:`<div class="promo-image-empty">Rasm tanlanmagan</div>`}<div><label class="btn primary sm">Chap banner rasmi<input type="file" hidden accept="image/jpeg,image/png,image/webp" onchange="setHomePromoImage('left',event)"></label>${pl.image?` <button class="btn danger sm" type="button" onclick="removeHomePromoImage('left')">Rasmni olib tashlash</button>`:''}</div></div><label>Chap sarlavha UZ<input id="leftTitleUz" value="${esc(pl.title?.uz||'')}"></label><label>Chap sarlavha RU<input id="leftTitleRu" value="${esc(pl.title?.ru||'')}"></label><label>Chap matn UZ<input id="leftTextUz" value="${esc(pl.text?.uz||'')}"></label><label>Chap matn RU<input id="leftTextRu" value="${esc(pl.text?.ru||'')}"></label><label>Tugma UZ<input id="leftBtnUz" value="${esc(pl.button?.uz||'')}"></label><label>Tugma RU<input id="leftBtnRu" value="${esc(pl.button?.ru||'')}"></label>
<h3 class="wide section-card">Bosh sahifa — o‘ng promo banner</h3><div class="wide promo-image-editor">${pr.image?`<img src="${pr.image}" alt="O‘ng promo">`:`<div class="promo-image-empty">Rasm tanlanmagan</div>`}<div><label class="btn primary sm">O‘ng banner rasmi<input type="file" hidden accept="image/jpeg,image/png,image/webp" onchange="setHomePromoImage('right',event)"></label>${pr.image?` <button class="btn danger sm" type="button" onclick="removeHomePromoImage('right')">Rasmni olib tashlash</button>`:''}</div></div><label>O‘ng sarlavha UZ<input id="rightTitleUz" value="${esc(pr.title?.uz||'')}"></label><label>O‘ng sarlavha RU<input id="rightTitleRu" value="${esc(pr.title?.ru||'')}"></label><label>O‘ng matn UZ<input id="rightTextUz" value="${esc(pr.text?.uz||'')}"></label><label>O‘ng matn RU<input id="rightTextRu" value="${esc(pr.text?.ru||'')}"></label><label>Tugma UZ<input id="rightBtnUz" value="${esc(pr.button?.uz||'')}"></label><label>Tugma RU<input id="rightBtnRu" value="${esc(pr.button?.ru||'')}"></label>
<h3 class="wide section-card">Katalog</h3><label>Katalog yozuvi UZ<input id="catalogEyebrowUz" value="${esc(ce.uz||'')}"></label><label>Katalog yozuvi RU<input id="catalogEyebrowRu" value="${esc(ce.ru||'')}"></label>
<h3 class="wide section-card">Xizmat afzalliklari</h3>${[0,1,2,3].map((i)=>{const x=bn[i]||{};return `<label>${i+1}-nom UZ<input id="b${i}tu" value="${esc(x.title?.uz||'')}"></label><label>${i+1}-nom RU<input id="b${i}tr" value="${esc(x.title?.ru||'')}"></label><label>${i+1}-matn UZ<input id="b${i}xu" value="${esc(x.text?.uz||'')}"></label><label>${i+1}-matn RU<input id="b${i}xr" value="${esc(x.text?.ru||'')}"></label>`}).join('')}
<h3 class="wide section-card">Biz haqimizda</h3><label class="wide">Sarlavha UZ<input id="aboutTitleUz" value="${esc(s.about?.uz?.title||'')}"></label><label class="wide">Matn UZ<textarea id="aboutTextUz">${esc(s.about?.uz?.text||'')}</textarea></label><label class="wide">Sarlavha RU<input id="aboutTitleRu" value="${esc(s.about?.ru?.title||'')}"></label><label class="wide">Matn RU<textarea id="aboutTextRu">${esc(s.about?.ru?.text||'')}</textarea></label>
<h3 class="wide section-card">Korxona rekvizitlari</h3><label class="wide">Firma nomi<input id="companyNameEdit" value="${esc(co.name||'')}"></label><label>STIR (INN)<input id="companyTaxEdit" value="${esc(co.taxId||'')}"></label><label>Bank kodi (MFO)<input id="companyMfoEdit" value="${esc(co.mfo||'')}"></label><label class="wide">Hisob raqami<input id="companyAccountEdit" value="${esc(co.account||'')}"></label>
<h3 class="wide section-card">Parkent xaritasi</h3><label class="wide">Ustki yozuv<input id="mapEyebrowEdit" value="${esc(mp.eyebrow||'')}"></label><label class="wide">Sarlavha<input id="mapTitleEdit" value="${esc(mp.title||'')}"></label><label class="wide">Matn<textarea id="mapTextEdit">${esc(mp.text||'')}</textarea></label><label class="wide">Xarita iframe manzili<input id="mapEmbedEdit" value="${esc(mp.embedUrl||'')}"></label><label class="wide">Katta xarita havolasi<input id="mapOpenEdit" value="${esc(mp.openUrl||'')}"></label>
<h3 class="wide section-card">Aloqa</h3><label class="wide">Sarlavha UZ<input id="contactTitleUz" value="${esc(s.contact?.uz?.title||'')}"></label><label class="wide">Matn UZ<textarea id="contactTextUz">${esc(s.contact?.uz?.text||'')}</textarea></label><label class="wide">Sarlavha RU<input id="contactTitleRu" value="${esc(s.contact?.ru?.title||'')}"></label><label class="wide">Matn RU<textarea id="contactTextRu">${esc(s.contact?.ru?.text||'')}</textarea></label>
<h3 class="wide section-card">Footer</h3><label>1-xizmat yozuvi<input id="footerService1Edit" value="${esc(ft.service1||'')}"></label><label>2-xizmat yozuvi<input id="footerService2Edit" value="${esc(ft.service2||'')}"></label><label class="wide">Copyright<input id="copyrightEdit" value="${esc(ft.copyright||'')}"></label>
<h3 class="wide section-card">SEO</h3><label class="wide">Meta title<input id="seoTitle" value="${esc(s.seo?.title||'')}"></label><label class="wide">Meta description<textarea id="seoDesc">${esc(s.seo?.description||'')}</textarea></label><label class="wide">Keywords<input id="seoKeywords" value="${esc(s.seo?.keywords||'')}"></label></div><div class="pages-savebar"><button class="btn primary" onclick="savePages()">Barcha sahifa sozlamalarini saqlash</button></div></div>`}
function setSiteLogo(e){const file=e.target.files?.[0];if(!file)return;if(!/^image\/(jpeg|png|webp)$/.test(file.type)){alert('Faqat JPG, PNG yoki WEBP rasm tanlang.');return}if(file.size>8*1024*1024){alert('Rasm 8 MB dan katta bo‘lmasin.');return}const img=new Image(),reader=new FileReader();reader.onload=()=>{img.onload=()=>{const max=1200,scale=Math.min(1,max/Math.max(img.width,img.height)),w=Math.max(1,Math.round(img.width*scale)),h=Math.max(1,Math.round(img.height*scale)),c=document.createElement('canvas');c.width=w;c.height=h;c.getContext('2d').drawImage(img,0,0,w,h);try{D.logo=c.toDataURL('image/webp',.9)}catch{D.logo=c.toDataURL('image/jpeg',.9)};renderPane()};img.src=reader.result};reader.readAsDataURL(file)}
function removeSiteLogo(){D.logo='';renderPane()}
function setHomePromoImage(side,e){const file=e.target.files?.[0];if(!file)return;optimizeSlideFile(file,data=>{D.settings.homePromos=D.settings.homePromos||{};D.settings.homePromos[side]=D.settings.homePromos[side]||{};D.settings.homePromos[side].image=data;renderPane()})}
function removeHomePromoImage(side){D.settings.homePromos=D.settings.homePromos||{};D.settings.homePromos[side]=D.settings.homePromos[side]||{};D.settings.homePromos[side].image='';renderPane()}
async function savePages(){const s=D.settings;s.siteName=$('#siteName').value.trim();s.siteDomain=$('#siteDomain').value.trim();s.theme=$('#theme').value;s.phone=$('#phone').value.trim();s.telegram=$('#telegram').value.trim();s.email=$('#email').value.trim();s.ui=s.ui||{};s.ui.logoSize=Math.max(48,Math.min(100,Number($('#logoSize').value)||68));s.testMode=s.testMode||{};s.testMode.active=$('#testModeActive').checked;s.testMode.text=$('#testModeText').value.trim()||'Saytimiz hozirda test rejimida ishlamoqda';s.tagline=s.tagline||{};s.tagline.uz=$('#tagUz').value;s.tagline.ru=$('#tagRu').value;s.homePromos=s.homePromos||{};for(const k of ['left','center','right'])s.homePromos[k]=s.homePromos[k]||{};s.homePromos.center.title={uz:$('#centerTitleUz').value,ru:$('#centerTitleRu').value};s.homePromos.center.text={uz:$('#centerTextUz').value,ru:$('#centerTextRu').value};s.homePromos.left.title={uz:$('#leftTitleUz').value,ru:$('#leftTitleRu').value};s.homePromos.left.text={uz:$('#leftTextUz').value,ru:$('#leftTextRu').value};s.homePromos.left.button={uz:$('#leftBtnUz').value,ru:$('#leftBtnRu').value};s.homePromos.right.title={uz:$('#rightTitleUz').value,ru:$('#rightTitleRu').value};s.homePromos.right.text={uz:$('#rightTextUz').value,ru:$('#rightTextRu').value};s.homePromos.right.button={uz:$('#rightBtnUz').value,ru:$('#rightBtnRu').value};s.catalogUi=s.catalogUi||{};s.catalogUi.eyebrow={uz:$('#catalogEyebrowUz').value,ru:$('#catalogEyebrowRu').value};s.benefits=[0,1,2,3].map(i=>({title:{uz:$('#b'+i+'tu').value,ru:$('#b'+i+'tr').value},text:{uz:$('#b'+i+'xu').value,ru:$('#b'+i+'xr').value}}));s.about=s.about||{};s.about.uz={title:$('#aboutTitleUz').value,text:$('#aboutTextUz').value};s.about.ru={title:$('#aboutTitleRu').value,text:$('#aboutTextRu').value};s.company=s.company||{};s.company.name=$('#companyNameEdit').value;s.company.taxId=$('#companyTaxEdit').value;s.company.mfo=$('#companyMfoEdit').value;s.company.account=$('#companyAccountEdit').value;s.map=s.map||{};s.map.eyebrow=$('#mapEyebrowEdit').value;s.map.title=$('#mapTitleEdit').value;s.map.text=$('#mapTextEdit').value;s.map.embedUrl=$('#mapEmbedEdit').value;s.map.openUrl=$('#mapOpenEdit').value;s.contact=s.contact||{};s.contact.uz={title:$('#contactTitleUz').value,text:$('#contactTextUz').value};s.contact.ru={title:$('#contactTitleRu').value,text:$('#contactTextRu').value};s.footer=s.footer||{};s.footer.service1=$('#footerService1Edit').value;s.footer.service2=$('#footerService2Edit').value;s.footer.copyright=$('#copyrightEdit').value;s.seo=s.seo||{};s.seo.title=$('#seoTitle').value;s.seo.description=$('#seoDesc').value;s.seo.keywords=$('#seoKeywords').value;await saveSettings('Barcha sahifa sozlamalari saqlandi')}

async function saveSettings(msg){try{await api('/api/admin/catalog',{method:'PUT',body:JSON.stringify({products:D.products,categories:D.categories,settings:D.settings,logo:D.logo})});alert(msg);await refresh()}catch(e){alert(e.message)}}
function auditPane(){return `<div class="panel"><div class="toolbar"><a class="btn primary sm" href="/api/admin/backup.json">Backup yuklash</a><label class="btn ghost sm">Backup tiklash<input id="restoreFile" type="file" accept="application/json" hidden onchange="restoreBackup(event)"></label></div><div class="notice">Audit log admin, operator, Telegram va mijoz tomonidan bajarilgan asosiy harakatlarni qayd qiladi.</div><div class="audit-list">${D.audit.map(a=>`<div class="audit-item"><span>${new Date(a.at).toLocaleString('uz-UZ')}</span><b>${esc(a.user)}</b><span>${esc(a.action)}</span><span>${esc(a.details)}</span></div>`).join('')}</div></div>`}
async function restoreBackup(e){const f=e.target.files[0];if(!f)return;try{const txt=await f.text();const data=JSON.parse(txt);await api('/api/admin/restore',{method:'POST',body:JSON.stringify(data)});alert('Backup tiklandi');await refresh()}catch(err){alert(err.message)}}
initAdminRealtime();
boot();
